void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
auto&named(auto&rows,std::string_view name){using Row=typename std::remove_reference_t<decltype(rows)>::value_type;using Ptr=std::conditional_t<std::is_const_v<std::remove_reference_t<decltype(rows)>>,const Row*,Row*>;Ptr p=nullptr;for(auto&v:rows)if(v.name&&name==v.name){need(!p,"Selection probe duplicate native field");p=&v;}need(p,"Selection probe native field unavailable");return *p;}
auto raw_rng(const LiveSessionState&s){std::array<SimulationRandomState,2>out;for(std::size_t k=0;k<2;++k){const auto&v=s.world.progression.random[k];out[k]={v.seed,v.calls,v.resets};}return out;}
auto live_rng(const LiveSessionState&s){return std::array{s.random.map.state(),s.random.gameplay.state()};}
std::string specialization(const LiveSessionState&s,std::int64_t p){return bnw_grand_native_component_revision(s,p,named(s.world.all_players->players.at(p).strategy.blocks,"city_specialization_ai"));}
std::string flavor(const LiveSessionState&s,std::int64_t p){const auto&f=named(s.world.all_players->players.at(p).knowledge.blocks,"flavor_manager");saves::PlayerStrategyBlock proxy{f.name,f.start_offset,f.end_offset,f.fields,f.arrays,f.hashes};return bnw_grand_native_component_revision(s,p,proxy);}
struct Snapshot {
 const LiveSessionState*world=nullptr,*source=nullptr;const LuaScriptHost*vm=nullptr;
 std::string grand,specialization,flavor,roster,source_grand;
 std::array<SimulationRandomState,2>raw{},live{},source_raw{},source_live{};
 BnwGrandSelectionProbeCounters counters;
 bool operator==(const Snapshot&)const=default;
};
Snapshot snapshot(const BnwTeamTechLuaEpoch&e,std::int64_t p,const BnwGrandSelectionProbeObserver&observe){need(e.world&&e.source_world&&e.host,"Selection probe missing retained epoch");return {e.world.get(),e.source_world,e.host.get(),bnw_grand_native_component_revision(*e.world,p),specialization(*e.world,p),flavor(*e.world,p),bnw_grand_military_inputs_revision(*e.world),bnw_grand_native_component_revision(*e.source_world,p),raw_rng(*e.world),live_rng(*e.world),raw_rng(*e.source_world),live_rng(*e.source_world),observe()};}
void no_grant(const BnwGameActivationExecution&flow,const BnwGrandSelectionProbeCounters&c){need(!flow.draft&&flow.pending_happiness&&flow.completed_steps.size()==14&&flow.player_turn_calls==1&&!flow.unit_turn_calls&&flow.completed_player_phases==std::vector{BnwTurnPhase::player_cache,BnwTurnPhase::player_ai_pre}&&flow.pending_happiness->activation_owner().completed.empty()&&!c.lua_publishes&&!c.can_continue,"Selection probe granted Grand/turn/publication/readiness");}
template<class F>void refusal(F&&f){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}need(rejected,"Selection post seal accepted stale input");}
void rejected_entry(BnwGameActivationExecution&flow,BnwTeamTechLuaEpoch&e,const SavedContentProfile&profile,const content::RulesDatabase&db,std::int64_t p,const BnwGrandSelectionProbeObserver&observe){const auto before=snapshot(e,p,observe);const auto result=continue_bnw_game_activation_grand_selection(flow,profile,db);need(result.outcome==LiveActionOutcome::rejected&&!flow.pending_happiness->happiness().grand_selection()&&snapshot(e,p,observe)==before,"Rejected selection wrote native/RNG/VM/journal or replayed callbacks");no_grant(flow,observe());}
void stale_entry(BnwGameActivationExecution&flow,BnwTeamTechLuaEpoch&e,const SavedContentProfile&profile,const content::RulesDatabase&db,std::int64_t p,const BnwGrandSelectionProbeObserver&observe){
 const auto original=snapshot(e,p,observe);
 const auto*source=e.source_world;LiveSessionState foreign=*source;e.source_world=&foreign;rejected_entry(flow,e,profile,db,p,observe);e.source_world=source;
 const auto map=e.world->random.map;e.world->random.map.draw(1);rejected_entry(flow,e,profile,db,p,observe);e.world->random.map=map;
 const auto game=e.world->random.gameplay;e.world->random.gameplay.draw(1);rejected_entry(flow,e,profile,db,p,observe);e.world->random.gameplay=game;
 ++e.world->world.progression.random[0].calls;rejected_entry(flow,e,profile,db,p,observe);--e.world->world.progression.random[0].calls;
 auto&prefix=*const_cast<LiveSessionState*>(e.source_world);const auto prefix_rng=prefix.random.gameplay;prefix.random.gameplay.draw(1);rejected_entry(flow,e,profile,db,p,observe);prefix.random.gameplay=prefix_rng;
 auto actual_vm=std::move(e.host);e.host=std::make_unique<LuaScriptHost>(ScriptBudget{8*1024*1024,1000000});e.host->complete_loading();rejected_entry(flow,e,profile,db,p,observe);e.host=std::move(actual_vm);
 auto changed=db.clone_gameplay();changed->apply_sql("CREATE TABLE CivisGrandSelectionStaleProbe(Value INTEGER)");changed->seal_immutable_preview_fingerprints();rejected_entry(flow,e,profile,*changed,p,observe);
 need(snapshot(e,p,observe)==original,"Selection entry stale probes did not restore the exact prefix");
}
