void configure_bnw_grand_selection_zero_tie_sql(content::RulesDatabase&db){db.apply_sql("UPDATE Defines SET Value=100 WHERE Name='AI_GRAND_STRATEGY_OTHER_PLAYERS_GS_MULTIPLIER'");const auto v=db.global_define("AI_GRAND_STRATEGY_OTHER_PLAYERS_GS_MULTIPLIER",content::GlobalDefineKind::integer);need(v.found&&v.error.empty()&&std::get<std::int64_t>(v.value)==100,"Selection fixture pressure100 Define unavailable");}
std::int32_t configure_bnw_grand_selection_zero_tie_inputs(LiveSessionState&w,std::int64_t p){need(w.world.all_players&&w.world.pregame&&w.world.teams&&p>=0&&p<22,"Selection fixture native roster unavailable");auto&g=named(w.world.all_players->players.at(p).strategy.blocks,"grand_strategy_ai");const auto team=w.setup.players.at(p).team;const auto&met=named(w.world.teams->teams.at(team).arrays,"has_met").values;std::int32_t denominator=0;for(std::int64_t other=0;other<22;++other)if(w.setup.players.at(other).alive&&met.at(w.setup.players.at(other).team))++denominator;need(denominator>0&&denominator*4<=22,"Selection tie fixture requires enough native guess slots");auto&guesses=named(g.arrays,"other_player_strategy_guesses").values;need(guesses.size()==22,"Selection fixture guesses22 unavailable");std::fill(guesses.begin(),guesses.end(),-1);for(std::int32_t slot=0;slot<4;++slot)for(std::int32_t n=0;n<denominator;++n)guesses[slot*denominator+n]=slot;
 named(g.fields,"active_strategy").value=-1;named(g.fields,"turns_since_active_set").value=7;
 need(!w.world.pregame->archive.flag_arrays.at("minor_nation_civs").at(p),"Selection positive fixture must use actual nonminor actor");auto&spec=named(w.world.all_players->players.at(p).strategy.blocks,"city_specialization_ai");named(spec.fields,"specializations_dirty").value=0;named(spec.fields,"interrupt_wonders").value=1;return denominator;
}
void probe_bnw_grand_selection_missing_minimum(BnwGameActivationExecution&flow,BnwTeamTechLuaEpoch&e,const SavedContentProfile&profile,const content::RulesDatabase&db,const BnwGrandWorldAverageRules&r,const BnwHappinessSuffixRules&n,const BnwGrandSelectionProbeObserver&observe){const auto*pressure=flow.pending_happiness->happiness().grand_pressure();need(pressure,"Selection missing-MinAge probe needs actual pressure");const auto p=pressure->player();const auto&q=checked_bnw_grand_pressure(*pressure,e,r,n,db);need(q.active_strategy>=0,"Selection missing-MinAge case requires actual valid current strategy");const auto before=snapshot(e,p,observe);const auto result=continue_bnw_game_activation_grand_selection(flow,profile,db);need(result.outcome==LiveActionOutcome::rejected&&result.reason.find("cached GC minimum-age owner unavailable")!=std::string::npos&&!flow.pending_happiness->happiness().grand_selection()&&snapshot(e,p,observe)==before,"Selection skipped unavailable genuine cached MinAge or lost pressure prefix");rejected_entry(flow,e,profile,db,p,observe);stale_entry(flow,e,profile,db,p,observe);need(checked_bnw_grand_pressure(*pressure,e,r,n,db).age_after==q.age_after,"Selection refusal invalidated retained actual pressure/age");}
