 const auto result=continue_bnw_game_activation_grand_selection(flow,profile,db);need(result.outcome==LiveActionOutcome::committed,result.reason.c_str());const auto*selection=flow.pending_happiness->happiness().grand_selection();need(selection,"Selection accepted no private retained pending");const auto&q=checked_bnw_grand_selection(*selection,e,r,n,db);const auto after=snapshot(e,p,observe);need(q.active_before==-1&&q.incremented_age==8&&!q.minimum_age&&q.decision.evaluated&&!q.decision.minimum_age_read&&q.decision.best_strategy==0&&q.decision.best_priority==0&&q.decision.slots_visited==4&&q.decision.active_written&&q.decision.active_after==0&&q.decision.age_after==0&&q.decision.specialization_called&&q.minor==false&&q.dirty_before==false&&q.dirty_after==true&&q.dirty_written&&q.interrupt_wonders==true&&q.frontier==BnwGrandSelectionFrontier::city_specialization_log&&q.pressure_log_changes==prior.log_changes,"Selection strict-first/source-short-circuit/SetActive/dirty-before-logger prefix differs");need(after.grand==expected_grand&&after.specialization==expected_spec_revision&&after.flavor==before.flavor&&after.roster==before.roster&&after.source_grand==before.source_grand&&after.raw==before.raw&&after.live==before.live&&after.source_raw==before.source_raw&&after.source_live==before.source_live&&after.counters==before.counters,"Selection changed unowned flavor/roster/source/RNG or called Lua/publication");need(result.reason.find("mandatory LogSpecializationUpdate then LogGrandStrategies")!=std::string::npos&&selection->frontier().find("NO Grand receipt")!=std::string::npos,"Selection omitted actual logging obligations");no_grant(flow,observe());
 refusal([&]{(void)checked_bnw_grand_pressure(*pressure,e,r,n,db);});need(continue_bnw_game_activation_grand_selection(flow,profile,db).outcome==LiveActionOutcome::rejected&&snapshot(e,p,observe)==after,"Selection wrapper replay wrote/reissued source effects");refusal([&]{(void)stage_bnw_grand_selection(*flow.pending_happiness,e,r,n,db);});need(snapshot(e,p,observe)==after,"Direct selection replay changed retained native prefix");
 const auto stale=[&]{refusal([&]{(void)checked_bnw_grand_selection(*selection,e,r,n,db);});};auto&age=named(named(e.world->world.all_players->players.at(p).strategy.blocks,"grand_strategy_ai").fields,"turns_since_active_set").value;++age;stale();--age;auto&dirty=named(named(e.world->world.all_players->players.at(p).strategy.blocks,"city_specialization_ai").fields,"specializations_dirty").value;dirty=0;stale();dirty=1;auto&wonders=named(named(e.world->world.all_players->players.at(p).strategy.blocks,"city_specialization_ai").fields,"interrupt_wonders").value;wonders=0;stale();wonders=1;const auto game=e.world->random.gameplay;e.world->random.gameplay.draw(1);stale();e.world->random.gameplay=game;const auto*source=e.source_world;LiveSessionState foreign=*source;e.source_world=&foreign;stale();e.source_world=source;auto vm=std::move(e.host);e.host=std::make_unique<LuaScriptHost>(ScriptBudget{8*1024*1024,1000000});e.host->complete_loading();stale();e.host=std::move(vm);need(snapshot(e,p,observe)==after&&checked_bnw_grand_selection(*selection,e,r,n,db).decision.best_strategy==0,"Restored selection postcheck lost exact pending values");no_grant(flow,observe());
